<template><SuperAdminLayout><header><div><p>PLATFORM FINANCIAL REPORT</p><h1>Sales Tax Master Report</h1><small>Paid software-service invoices from all customer companies.</small></div><button @click="download">⇩ Download CSV</button></header><form class="filters" @submit.prevent="load"><label>From date<input v-model="filters.from_date" type="date"/></label><label>To date<input v-model="filters.to_date" type="date"/></label><button>Generate report</button></form><p v-if="error" class="error">{{error}}</p><section class="totals"><div><span>Invoice Subtotal</span><strong>{{money(data.totals?.subtotal)}}</strong></div><div><span>Tax Collected</span><strong>{{money(data.totals?.tax)}}</strong></div><div><span>Total Paid</span><strong>{{money(data.totals?.total)}}</strong></div></section><section class="card"><table><thead><tr><th>Customer</th><th>Date</th><th>Invoice</th><th>Service Plan</th><th>Subtotal</th><th>GST</th><th>Total Paid</th></tr></thead><tbody><tr v-for="row in data.rows||[]" :key="row.invoice_number"><td>{{row.customer}}</td><td>{{pretty(row.date)}}</td><td>{{row.invoice_number}}</td><td>{{row.plan}}</td><td>{{money(row.subtotal,row.currency)}}</td><td>{{money(row.tax,row.currency)}}</td><td>{{money(row.total,row.currency)}}</td></tr><tr v-if="!(data.rows||[]).length"><td colspan="7" class="empty">No paid invoices found in this report period.</td></tr></tbody></table></section></SuperAdminLayout></template>
<script setup>import{onMounted,ref}from'vue';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const now=new Date(),date=v=>new Date(v.getFullYear(),v.getMonth(),v.getDate()).toISOString().slice(0,10),filters=ref({from_date:date(new Date(now.getFullYear(),now.getMonth(),1)),to_date:date(now)}),data=ref({rows:[],totals:{}}),error=ref('');const money=(v,c='CAD')=>Number(v||0).toLocaleString('en-CA',{style:'currency',currency:c});const pretty=v=>v?new Intl.DateTimeFormat('en-CA',{month:'short',day:'numeric',year:'numeric'}).format(new Date(`${v}T00:00:00`)):'—';const load=async()=>{error.value='';try{const res=await client.get('/super-admin/tax-report',{params:filters.value});data.value=res.data.data}catch(e){error.value=e?.response?.data?.message||'Unable to load tax report.'}};const download=()=>{const rows=[['Sales Tax Master Report',`${filters.value.from_date} to ${filters.value.to_date}`],['Customer','Date','Invoice','Plan','Subtotal','Tax','Total'],...(data.value.rows||[]).map(r=>[r.customer,r.date,r.invoice_number,r.plan,r.subtotal,r.tax,r.total])];const url=URL.createObjectURL(new Blob([rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='sales-tax-master-report.csv';a.click();URL.revokeObjectURL(url)};onMounted(load)</script>
<style scoped>header{display:flex;justify-content:space-between;align-items:start;margin-bottom:18px}header p{margin:0;color:#2877ce;font-size:.72rem;font-weight:700;letter-spacing:.1em}h1{margin:5px 0;font-size:2rem}header small{color:#718096}button{border:0;border-radius:6px;background:#156ad1;color:#fff;padding:10px 16px}.filters{display:flex;align-items:end;gap:12px;background:#fff;border:1px solid #e3e8f1;border-radius:9px;padding:15px;margin-bottom:16px}.filters label{display:grid;gap:5px;font-size:.78rem;font-weight:600;color:#536275}.filters input{border:1px solid #d9e1ee;border-radius:6px;padding:9px;font:inherit}.totals{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:16px}.totals div,.card{background:#fff;border:1px solid #e3e8f1;border-radius:9px}.totals div{padding:17px}.totals span{font-size:.78rem;color:#718096}.totals strong{display:block;font-size:1.35rem;margin-top:5px}.card{padding:18px;overflow:auto}table{border-collapse:collapse;width:100%;min-width:840px;font-size:.84rem}th{text-align:left;color:#718096;font-size:.75rem;padding:0 0 10px}td{padding:13px 0;border-top:1px solid #edf1f6}.empty{text-align:center;color:#8a98ab}.error{color:#b42318}@media(max-width:650px){header{display:block}header button{margin-top:12px}.filters{align-items:stretch;display:grid}.totals{grid-template-columns:1fr}}</style>
